#!/usr/bin/env python3
"""Verifier for EP-364 (consecutive powerful triples) campaign.
Input: submission directory containing find.json per proposition pin://a6e59ac3c7f8ce08d6bd7cea46dd39f774195fbd02040bf0e017db99ab4f7ea4i0
Output: JSON {"verdict": "pass"|"fail"|"invalid", "reason": str}; exit 0 iff pass.
Pass conditions:
 - triple: verifier independently recomputes full powerfulness for n, n+1, n+2
   (factor each integer from scratch; submitted factorizations must also be consistent).
 - negative: provided search script rerun by verifier over a sampled sub-interval;
   sampled rerun must find no triple AND agree with log counts on sampled ranges.
"""
import json, os, subprocess, sys, tempfile
from math import isqrt

def emit(v, r):
    print(json.dumps({"verdict": v, "reason": r}, ensure_ascii=False))
    sys.exit(0 if v == "pass" else 1)

def factorize(n):
    fs, d = [], 2
    while d * d <= n:
        if n % d == 0:
            e = 0
            while n % d == 0:
                n //= d; e += 1
            fs.append((d, e))
        d += 1 if d == 2 else 2
    if n > 1: fs.append((n, 1))
    return fs

def is_powerful(n):
    return all(e >= 2 for _, e in factorize(n))

def main():
    if len(sys.argv) < 2: emit("invalid", "no submission path")
    sub = sys.argv[1]
    f = os.path.join(sub, "find.json")
    if not os.path.isfile(f): emit("invalid", "find.json missing")
    try:
        d = json.load(open(f))
    except Exception as e:
        emit("invalid", f"unparseable find.json: {e}")
    t = d.get("type")
    if t == "triple":
        try:
            n = int(d["n"])
        except Exception:
            emit("invalid", "bad n")
        if n < 2: emit("fail", "n must be >= 2")
        checks = [(m, factorize(m), all(e >= 2 for _, e in factorize(m))) for m in (n, n + 1, n + 2)]
        bad = [m for m, _, ok in checks if not ok]
        if bad:
            emit("fail", f"not powerful: {bad}; factorizations {[(m, fs) for m, fs, _ in checks]}")
        # cross-check submitted factorizations if present
        facs = d.get("factorizations") or {}
        for key, m in (("n", n), ("n+1", n + 1), ("n+2", n + 2)):
            if key in facs:
                try:
                    claimed = sorted((int(p), int(e)) for p, e in facs[key])
                except Exception:
                    emit("fail", f"bad claimed factorization for {key}")
                if claimed != sorted(factorize(m)):
                    emit("fail", f"claimed factorization mismatch for {key}={m}")
        emit("pass", f"verified powerful triple: ({n}, {n+1}, {n+2}) " +
             "; ".join(f"{m}={fs}" for m, fs, _ in checks))
    elif t == "negative":
        try:
            lo, hi = int(d["from"]), int(d["to"])
        except Exception:
            emit("invalid", "bad from/to")
        script = os.path.join(sub, d.get("script", "search.py"))
        if not os.path.isfile(script): emit("invalid", "search script missing")
        if hi <= lo: emit("invalid", "empty range")
        span = hi - lo
        # sample up to 3 sub-intervals covering 1% of range
        sample = max(10 ** 4, span // 100)
        with tempfile.TemporaryDirectory() as td:
            for k in range(3):
                a = lo + (span * k) // 3
                b = min(hi, a + sample)
                if b <= a: continue
                try:
                    r = subprocess.run([sys.executable, script, "--from", str(a), "--to", str(b)],
                                       capture_output=True, text=True, timeout=3600, cwd=sub)
                except subprocess.TimeoutExpired:
                    emit("fail", f"script timeout on sample [{a},{b})")
                if r.returncode != 0:
                    emit("fail", f"script error on [{a},{b}): {(r.stderr or '')[-400:]}")
                try:
                    out = json.loads(r.stdout.strip().splitlines()[-1])
                except Exception:
                    emit("fail", f"unparseable script output on [{a},{b})")
                if out.get("triples_found", 1) != 0:
                    emit("fail", f"sampled rerun FOUND triple in [{a},{b}) — log inconsistent with claim")
        emit("pass", f"negative record verified on sampled intervals; claimed range [{lo},{hi})")
    else:
        emit("invalid", f"unknown type {t}")

if __name__ == "__main__":
    main()
